import{_ as r,o as s,c as t,ag as a}from"./chunks/framework.CPuifXUY.js";const m=JSON.parse('{"title":"Avant de commencer","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"demarrer.md","filePath":"demarrer.md"}'),o={name:"demarrer.md"};function n(i,e,u,l,c,p){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="avant-de-commencer" tabindex="-1">Avant de commencer <a class="header-anchor" href="#avant-de-commencer" aria-label="Permalink to &quot;Avant de commencer&quot;">​</a></h1><h2 id="ta-checklist" tabindex="-1">Ta checklist <a class="header-anchor" href="#ta-checklist" aria-label="Permalink to &quot;Ta checklist&quot;">​</a></h2><ul><li>[ ] <strong>Inscris-toi à ta session prérequis</strong>, « Sous le capot » (version technique ou non technique selon ton profil). Elle se suit en session avec un formateur, sur inscription, et passe avant l&#39;auto-formation.</li><li>[ ] <strong>Vérifie ton accès à l&#39;assistant IA autorisé dans ton entreprise</strong> (ChatGPT, Claude, Microsoft Copilot…). Chaque auto-formation se suit avec lui ouvert à côté.</li><li>[ ] <strong>Bloque du temps</strong> : une auto-formation dure environ 3 heures, en modules de 15 à 20 minutes. Tu peux la suivre en plusieurs créneaux.</li><li>[ ] <strong>Garde la même machine et le même navigateur</strong> : ta progression dans une auto-formation reste dans ton navigateur, rien n&#39;est transmis.</li><li>[ ] <strong>Note la date du hackathon</strong> sur la page <a href="/ai-speed-training.web/parcours/programme">Programme</a>.</li></ul><h2 id="questions-frequentes" tabindex="-1">Questions fréquentes <a class="header-anchor" href="#questions-frequentes" aria-label="Permalink to &quot;Questions fréquentes&quot;">​</a></h2><p><strong>Dois-je suivre le prérequis si je connais déjà l&#39;IA ?</strong> Oui. Il donne à toute l&#39;équipe le même vocabulaire, celui des auto-formations et du hackathon. Le module M0 de chaque auto-formation le recoupe : si tu as suivi le prérequis, tu peux le parcourir rapidement.</p><p><strong>Technique ou non technique ?</strong> Le profil Produit suit la version non technique, le profil Tech la version technique. Un tech manager choisit l&#39;une ou l&#39;autre.</p><p><strong>Je suis PM : par quoi commencer ?</strong> Le parcours PO est recommandé avant le parcours PM : le M0 du PM part de ce que le PO a vu.</p><p><strong>Je suis développeur : les deux parcours d&#39;un coup ?</strong> Non. Suis le parcours Développeur, pratique quelques semaines, puis passe au parcours Développeur avancé.</p><p><strong>Mon auto-formation affiche « Bientôt disponible ».</strong> Elle est en cours d&#39;écriture. Suis ton prérequis en attendant : tu seras prêt quand elle ouvrira.</p><p><strong>Puis-je utiliser mes vrais documents dans les exercices ?</strong> Les exercices portent sur des documents fictifs, qu&#39;on peut donner à l&#39;IA sans risque. Avec tes vrais documents, applique les règles de ton entreprise et pose-toi les questions du module M0.</p>',10)])])}const h=r(o,[["render",n]]);export{m as __pageData,h as default};
